  1→{% comment %}
  2→  Zip Code Checker — Cart Validator Block
  3→  Place this block on your Cart page template in the Theme Editor.
  4→  It reads the validation state set by the Zip Code Checker widget and
  5→  warns customers with non-serviceable ZIP codes before they check out.
  6→{% endcomment %}
  7→
  8→{% if request.design_mode %}
  9→  {%- comment -%} Theme Editor preview — show sample warning state {%- endcomment -%}
 10→  <div class="zcc-cart-warning zcc-cart-warning--preview" style="
 11→    background: #fff4f4;
 12→    border: 2px solid #d72c0d;
 13→    border-radius: 8px;
 14→    padding: 16px 20px;
 15→    margin: 16px 0;
 16→    font-family: inherit;
 17→  ">
 18→    <div style="display:flex; align-items:center; gap:10px;">
 19→      <span style="font-size:1.4em;">⚠️</span>
 20→      <div>
 21→        <strong style="color:#d72c0d; font-size:0.95em;">Delivery Not Available</strong>
 22→        <p style="margin:4px 0 0; font-size:0.85em; color:#6d7175;">
 23→          The Zip Code Checker Cart Validator is active. Customers with non-serviceable ZIP codes will see a warning here.
 24→        </p>
 25→      </div>
 26→    </div>
 27→  </div>
 28→{% else %}
 29→  {%- liquid
 30→    assign shop_domain = shop.permanent_domain
 31→    assign metafield_value = app.metafields.zip_checker.widget_config.value
 32→  -%}
 33→
 34→  <div id="zcc-cart-validator" style="display:none; margin: 16px 0;" aria-live="polite"></div>
 35→
 36→  <style>
 37→    #zcc-cart-validator { font-family: inherit; }
 38→    .zcc-cv-banner {
 39→      background: #fff4f4;
 40→      border: 2px solid #d72c0d;
 41→      border-radius: 8px;
 42→      padding: 16px 20px;
 43→      display: flex;
 44→      align-items: flex-start;
 45→      gap: 12px;
 46→    }
 47→    .zcc-cv-icon { font-size: 1.3em; flex-shrink: 0; margin-top: 2px; }
 48→    .zcc-cv-content { flex: 1; }
 49→    .zcc-cv-title {
 50→      color: #d72c0d;
 51→      font-weight: 700;
 52→      font-size: 0.95em;
 53→      margin: 0 0 4px;
 54→    }
 55→    .zcc-cv-msg {
 56→      color: #202223;
 57→      font-size: 0.875em;
 58→      margin: 0 0 8px;
 59→    }
 60→    .zcc-cv-zip {
 61→      font-weight: 700;
 62→      color: #d72c0d;
 63→    }
 64→    .zcc-cv-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 4px; }
 65→    .zcc-cv-dismiss {
 66→      background: none;
 67→      border: 1px solid #d72c0d;
 68→      color: #d72c0d;
 69→      border-radius: 4px;
 70→      padding: 4px 12px;
 71→      font-size: 0.8em;
 72→      cursor: pointer;
 73→    }
 74→    .zcc-cv-dismiss:hover { background: #d72c0d; color: #fff; }
 75→    .zcc-checkout-blocked { opacity: 0.4 !important; pointer-events: none !important; cursor: not-allowed !important; }
 76→    .zcc-checkout-notice {
 77→      font-size: 0.78em;
 78→      color: #d72c0d;
 79→      margin-top: 6px;
 80→      text-align: center;
 81→      display: none;
 82→    }
 83→  </style>
 84→
 85→  <script>
 86→  (function() {
 87→    var SHOP = {{ shop_domain | json }};
 88→    var META_RAW = {{ metafield_value | default: 'null' | json }};
 89→
 90→    var cfg = { blockCheckoutInCart: false };
 91→    try {
 92→      var meta = META_RAW ? JSON.parse(META_RAW) : null;
 93→      if (meta) cfg = Object.assign(cfg, meta);
 94→    } catch(e) {}
 95→
 96→    function init() {
 97→      var wrapper = document.getElementById('zcc-cart-validator');
 98→      if (!wrapper) return;
 99→
100→      var isValid, zip, storedShop;
101→      try {
102→        isValid = sessionStorage.getItem('zcc:valid');
103→        zip = sessionStorage.getItem('zcc:zip');
104→        storedShop = sessionStorage.getItem('zcc:shop');
105→      } catch(e) { return; }
106→
107→      // Only act if the stored validation is for THIS shop
108→      if (!isValid || storedShop !== SHOP) return;
109→
110→      if (isValid === 'false' && zip) {
111→        // Show warning banner
112→        wrapper.style.display = 'block';
113→        wrapper.innerHTML = '<div class="zcc-cv-banner">'
114→          + '<span class="zcc-cv-icon">⚠️</span>'
115→          + '<div class="zcc-cv-content">'
116→          + '<p class="zcc-cv-title">Delivery Not Available for Your Area</p>'
117→          + '<p class="zcc-cv-msg">Your ZIP code <span class="zcc-cv-zip">' + zip + '</span> is outside our current delivery area. Please remove restricted items or check a different ZIP code.</p>'
118→          + '<div class="zcc-cv-actions">'
119→          + '<button class="zcc-cv-dismiss" onclick="document.getElementById(\'zcc-cart-validator\').style.display=\'none\'">Dismiss</button>'
120→          + '</div>'
121→          + '</div>'
122→          + '</div>';
123→
124→        // Optionally block checkout buttons
125→        if (cfg.blockCheckoutInCart) {
126→          var CHECKOUT_SELECTORS = [
127→            '[name="checkout"]',
128→            '.cart__checkout-button',
129→            '.cart-checkout-btn',
130→            'button[data-action="checkout"]',
131→            '.checkout-button',
132→            'input[name="checkout"]',
133→            '[href="/checkout"]',
134→            'a.btn[href*="checkout"]'
135→          ];
136→
137→          CHECKOUT_SELECTORS.forEach(function(sel) {
138→            try {
139→              document.querySelectorAll(sel).forEach(function(el) {
140→                el.classList.add('zcc-checkout-blocked');
141→                el.setAttribute('data-zcc-checkout-blocked', 'true');
142→                el.setAttribute('title', 'Delivery is not available for ZIP code ' + zip + '. Please update your ZIP code.');
143→              });
144→            } catch(e) {}
145→          });
146→
147→          // Add notice below checkout buttons
148→          var notice = document.createElement('p');
149→          notice.className = 'zcc-checkout-notice';
150→          notice.style.display = 'block';
151→          notice.textContent = 'Checkout unavailable — ZIP code ' + zip + ' is not in our delivery area.';
152→          wrapper.appendChild(notice);
153→        }
154→      }
155→    }
156→
157→    // Run on DOM ready
158→    if (document.readyState === 'loading') {
159→      document.addEventListener('DOMContentLoaded', init);
160→    } else {
161→      init();
162→    }
163→
164→    // Also listen for zcc:validated events (if widget and cart are on same page)
165→    window.addEventListener('zcc:validated', function(e) {
166→      try {
167→        var detail = e.detail;
168→        if (!detail.valid) {
169→          sessionStorage.setItem('zcc:valid', 'false');
170→          sessionStorage.setItem('zcc:zip', detail.zip);
171→        } else {
172→          sessionStorage.removeItem('zcc:valid');
173→          sessionStorage.removeItem('zcc:zip');
174→          var w = document.getElementById('zcc-cart-validator');
175→          if (w) w.style.display = 'none';
176→          // Re-enable checkout buttons if they were blocked
177→          document.querySelectorAll('[data-zcc-checkout-blocked="true"]').forEach(function(el) {
178→            el.classList.remove('zcc-checkout-blocked');
179→            el.removeAttribute('data-zcc-checkout-blocked');
180→            el.removeAttribute('title');
181→          });
182→        }
183→      } catch(e) {}
184→    });
185→  })();
186→  </script>
