723→        '</div>' +
724→      '</div>' +
725→      '<button id="' + WID + '-trigger" type="button">' +
726→        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
727→        esc(cfg.buttonText || "Check Delivery") +
