757→  // ── Popup position ───────────────────────────────────────────────────────────
758→  function renderPopup(cfg, WID, rad) {
759→    injectCss(WID, cfg, rad);
760→
761→    var popupCss =
762→      "#" + WID + "-overlay{" +
763→        "display:none !important;position:fixed !important;inset:0 !important;" +
