766→      "}" +
767→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
768→      "#" + WID + "-modal{" +
769→        "background:" + cfg.backgroundColor + " !important;border-radius:16px !important;" +
770→        "max-width:480px !important;width:100% !important;position:relative !important;" +
771→        "box-shadow:0 24px 48px rgba(0,0,0,.2) !important;animation:zcc-slide-in 0.3s ease !important" +
772→      "}" +
773→      "#" + WID + "-modal .zcc-modal-header{" +
774→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
775→        "padding:20px 24px 0 !important" +
776→      "}" +
777→      "#" + WID + "-modal .zcc-modal-title{font-size:15px !important;font-weight:700 !important;color:" + cfg.textColor + " !important;display:flex !important;align-items:center !important;gap:8px !important}" +
778→      "#" + WID + "-modal .zcc-modal-close{" +
779→        "background:none !important;border:none !important;" +
780→        "cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5 !important;" +
781→        "padding:4px !important;border-radius:6px !important;transition:all 0.15s !important;line-height:1 !important" +
782→      "}" +
783→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important;background:#f6f6f7 !important}" +
784→      "#" + WID + "-popup-trigger{" +
785→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
786→        "border-radius:" + rad + " !important;padding:12px 28px !important;font-size:14px !important;font-weight:600 !important;" +
787→        "cursor:pointer !important;transition:all 0.2s ease !important;display:inline-flex !important;align-items:center !important;gap:8px !important" +
788→      "}" +
789→      "#" + WID + "-popup-trigger:hover{filter:brightness(1.08) !important;transform:translateY(-1px) !important;box-shadow:0 4px 12px " + cfg.primaryColor + "30 !important}";
790→
791→    var popupStyle = document.createElement("style");
792→    popupStyle.textContent = popupCss;
793→    document.head.appendChild(popupStyle);
794→
795→    // Trigger button renders in-place (inside the block)
796→    container.innerHTML =
797→      '<button id="' + WID + '-popup-trigger" type="button">' +
798→        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
799→        esc(cfg.heading) +
800→      '</button>';
801→
802→    // Overlay + modal append to body
803→    var overlay = document.createElement("div");
804→    overlay.id = WID + "-overlay";
805→    overlay.innerHTML =
806→      '<div id="' + WID + '-modal">' +
807→        '<div class="zcc-modal-header">' +
808→          '<span class="zcc-modal-title">' +
809→            '<svg viewBox="0 0 24 24" fill="none" stroke="' + escAttr(cfg.primaryColor) + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
810→            ' ' + esc(cfg.heading) + '</span>' +
811→          '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">' +
812→            '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:18px;height:18px"><path d="M18 6L6 18"/><path d="M6 6l12 12"/></svg>' +
813→          '</button>' +
814→        '</div>' +
815→        '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important">' +
816→          buildWidgetInner(WID, cfg, cfg.buttonText) +
817→        '</div>' +
818→      '</div>';
819→    document.body.appendChild(overlay);
820→
821→    var trigger = document.getElementById(WID + "-popup-trigger");
822→    var closeBtn = document.getElementById(WID + "-modal-close");
823→    var modal = document.getElementById(WID + "-modal");
824→
825→    function openPopup() { overlay.classList.add("zcc-open"); }
826→    function closePopup() { overlay.classList.remove("zcc-open"); }
827→
828→    if (trigger) trigger.addEventListener("click", openPopup);
829→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
830→
831→    // Close on overlay backdrop click (not modal content)
832→    overlay.addEventListener("click", function (e) {
833→      if (e.target === overlay) closePopup();
834→    });
835→
836→    // Close on Escape key
837→    document.addEventListener("keydown", function (e) {
838→      if (e.key === "Escape") closePopup();
839→    });
840→
841→    wireWidget(WID, cfg, API_BASE, SHOP);
842→  }
843→
844→  function esc(str) {
845→    return String(str)
846→      .replace(/&/g, "&amp;")
847→      .replace(/</g, "&lt;")
848→      .replace(/>/g, "&gt;")
849→      .replace(/"/g, "&quot;");
850→  }
851→
852→  function escAttr(str) {
853→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
854→  }
855→  } // end init()
856→})();
857→</script>
